window.TDV_VERSION="0.2.17";
window.TDV_CHANNEL="stable";

// Effective channel right now.
function tdvChannel(){
  var c=null;
  try{c=localStorage.getItem('tdv_channel')}catch(e){}
  if(c==='prerelease'||c==='stable')return c;
  return TDV_CHANNEL==='prerelease'?'prerelease':'stable';
}

// Switch channel. Choosing the build's own baked channel clears the override.
function tdvSetChannel(c){
  try{
    if(c===TDV_CHANNEL)localStorage.removeItem('tdv_channel');
    else localStorage.setItem('tdv_channel',c);
  }catch(e){}
}

// Split '1.2.3-4' -> [1,2,3,'4']  ('-pre.N' is still accepted while migrating)
function tdvVerParts(v){
  var m=/^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?$/.exec(String(v||''));
  if(!m)return[0,0,0,''];
  var pre=m[4]||'';
  // builds once baked as '-pre.N' now compare as their '-N' equivalent,
  // otherwise semver would rank 'pre' above any number and a tester on an
  // old build would never be offered the newer one
  if(/^pre\.\d+$/.test(pre))pre=pre.slice(4);
  return[+m[1],+m[2],+m[3],pre];
}

// Is version `a` strictly newer than version `b`?
//   0.2.12    > 0.2.11
//   0.2.11-1  > 0.2.11     <- deliberately NOT plain semver
//   0.2.11-2  > 0.2.11-1
//   0.2.12    > 0.2.11-9
//
// Plain semver ranks a pre-release BELOW its own final (0.2.11-1 < 0.2.11).
// That would make a pre-release undiscoverable to exactly the people it is
// for: a player sitting on stable 0.2.11 would never be offered 0.2.11-1.
// A pre-release of 0.2.11 carries content that hasn't shipped yet, so for
// them it IS the newer build. We flip that one case and keep normal semver
// for everything else. src-tauri/src/lib.rs mirrors this rule so the desktop
// updater agrees.
function tdvNewer(a,b){
  var A=tdvVerParts(a),B=tdvVerParts(b);
  for(var i=0;i<3;i++)if(A[i]!==B[i])return A[i]>B[i];
  if(A[3]===B[3])return false;
  if(!A[3])return false;                // A is the final of this base, B is a pre:
                                        // never an upgrade for someone who has it
  if(!B[3])return true;                 // A is a pre of this base, B is the final:
                                        // that's exactly the jump we want to offer
  // both pre-release: compare dot-separated identifiers (semver rules)
  var xs=String(A[3]).split('.'),ys=String(B[3]).split('.');
  for(var j=0;j<Math.max(xs.length,ys.length);j++){
    var x=xs[j],y=ys[j];
    if(x===undefined)return false;      // fewer identifiers sorts lower
    if(y===undefined)return true;
    var nx=/^\d+$/.test(x),ny=/^\d+$/.test(y);
    if(nx&&ny){if(+x!==+y)return +x>+y}
    else if(nx!==ny)return !nx;         // numeric < alphanumeric
    else if(x!==y)return x>y;
  }
  return false;
}
